#include <iostream>
#include <string>
#include <string_view>
#include <cctype>
#include <vector>

bool isValidSSN(std::string_view ssn) {
    if (ssn.length() != 11) return false;
    for (size_t i = 0; i < ssn.length(); ++i) {
        if (i == 3 || i == 6) {
            if (ssn[i] != '-') return false;
        } else {
            if (!std::isdigit(static_cast<unsigned char>(ssn[i]))) return false;
        }
    }
    return true;
}

void substitutePhrase(std::string& text, std::string_view target, std::string_view replacement) {
    size_t pos = 0;
    while ((pos = text.find(target, pos)) != std::string::npos) {
        text.replace(pos, target.length(), replacement);
        pos += replacement.length();
    }
}

int main() {
    std::string ssn1 = "123-45-6789";
    std::string ssn2 = "123-4A-6789";
    std::cout << ssn1 << " valid: " << (isValidSSN(ssn1) ? "true" : "false") << "\n";
    std::cout << ssn2 << " valid: " << (isValidSSN(ssn2) ? "true" : "false") << "\n";

    std::string recipe = "Take 1 cup butter and 1 cup sugar.";
    substitutePhrase(recipe, "1 cup butter", "1 cup yogurt");
    substitutePhrase(recipe, "1 cup sugar", "1/2 cup honey");
    std::cout << "Modified recipe: " << recipe << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>

std::string toLowerString(std::string_view sv) {
    std::string res;
    res.reserve(sv.size());
    for (char c : sv) {
        res.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
    }
    return res;
}

int calculateSpamScore(const std::string& message, const std::vector<std::string>& spamWords) {
    std::string lowerMsg = toLowerString(message);
    int score = 0;
    for (const auto& word : spamWords) {
        std::string lowerWord = toLowerString(word);
        size_t pos = 0;
        while ((pos = lowerMsg.find(lowerWord, pos)) != std::string::npos) {
            ++score;
            pos += lowerWord.length();
        }
    }
    return score;
}

int main() {
    std::vector<std::string> spamKeywords = {"winner", "free cash", "congratulations", "urgent"};
    std::string email = "Congratulations! You are the lucky WINNER of free cash. Urgent claim needed.";

    int score = calculateSpamScore(email, spamKeywords);
    std::cout << "Spam Score: " << score << "\n";
    if (score >= 3) {
        std::cout << "Verdict: High likelihood of spam.\n";
    } else {
        std::cout << "Verdict: Legitimate message.\n";
    }
    return 0;
}
